import{_ as a,o as t,c as s,a1 as n}from"./chunks/framework.CiMD_7j0.js";const h=JSON.parse('{"title":"Architecture & Request Flow","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"0f37daa7-8788-483f-92c2-5a0ee5a858de","PropagateID":"0f37daa7-8788-483f-92c2-5a0ee5a858de","ReservedCode1":"b4aa56e9-8897-4ced-bf11-1d0e24bdb9eb","ReservedCode2":"b4aa56e9-8897-4ced-bf11-1d0e24bdb9eb"}},"headers":[],"relativePath":"en/guide/go/architecture.md","filePath":"en/guide/go/architecture.md","lastUpdated":null}'),i={name:"en/guide/go/architecture.md"};function r(o,e,d,c,l,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture-request-flow" tabindex="-1">Architecture &amp; Request Flow <a class="header-anchor" href="#architecture-request-flow" aria-label="Permalink to &quot;Architecture &amp; Request Flow&quot;">​</a></h1><h2 id="application-startup" tabindex="-1">Application Startup <a class="header-anchor" href="#application-startup" aria-label="Permalink to &quot;Application Startup&quot;">​</a></h2><p><code>cmd/server/main.go</code> parses flags then calls <code>bootstrap.Run</code>, which starts in this order:</p><ol><li>Load config: Viper reads <code>configs/config.yaml</code>; env vars with the <code>GA_</code> prefix override it.</li><li>Initialize Zap structured logging (JSON).</li><li>Initialize GORM database: MySQL / SQLite auto-switch + connection pool (<code>max_open_conns: 50</code>).</li><li>Seed data: superadmin account + core menus.</li><li>Scan and register plugins: L1 <code>init()</code> self-registration + L2 declarative ZIP loading.</li><li>Register HTTP routes: public / auth / permission groups.</li><li>Start the MCP gateway.</li><li>Dispatch the <code>app_startup</code> event.</li></ol><h2 id="backend-layering" tabindex="-1">Backend Layering <a class="header-anchor" href="#backend-layering" aria-label="Permalink to &quot;Backend Layering&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP Request</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Middleware (request_id / cors / recovery / jwt_auth / permission / rate_limit / operation_log)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Gin Router (public / auth / permission groups)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Handler (api/*.go) → parameter binding + response format</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Service (service/) → business logic</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>DAL (dal/) → data access</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>GORM Model (model/, sys_ prefix)</span></span></code></pre></div><p>The Handler layer handles parameter binding and the unified response format <code>{ code, msg, data }</code>; business rules live in Service; DAL wraps GORM queries. Business exceptions are caught by the recovery middleware and converted to the same error structure.</p><h2 id="middleware-chain" tabindex="-1">Middleware Chain <a class="header-anchor" href="#middleware-chain" aria-label="Permalink to &quot;Middleware Chain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Middleware</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>request_id</code></td><td>Generates a unique ID per request, threading through the log chain</td></tr><tr><td><code>cors</code></td><td>Cross-origin handling; Origins controlled by config</td></tr><tr><td><code>recovery</code></td><td>Catches panics, returns 500 instead of crashing</td></tr><tr><td><code>logger</code></td><td>Request/response logging</td></tr><tr><td><code>jwt_auth</code></td><td>Parses Bearer tokens, validates JWT validity</td></tr><tr><td><code>login_guard</code></td><td>Login brute-force protection: 5 failures locks for 30 minutes</td></tr><tr><td><code>permission</code></td><td>RBAC authorization based on permission identifiers</td></tr><tr><td><code>rate_limit</code></td><td>300 requests/IP/minute, burst 50</td></tr><tr><td><code>operation_log</code></td><td>Operation logs written asynchronously to the audit queue</td></tr></tbody></table><h2 id="graceful-shutdown" tabindex="-1">Graceful Shutdown <a class="header-anchor" href="#graceful-shutdown" aria-label="Permalink to &quot;Graceful Shutdown&quot;">​</a></h2><p>After receiving a shutdown signal, shutdown runs in three phases, each with a 5-second timeout:</p><ol><li>Stop accepting new requests (5s).</li><li>Plugin unload + dispatch <code>app_shutdown</code> event (5s).</li><li>Drain logs + close database connections (5s).</li></ol>`,12)])])}const g=a(i,[["render",r]]);export{h as __pageData,g as default};
